insert into public.exercises (id, name, aliases, category, movement_pattern, mechanic, force, level, instructions, images, is_common, is_active, source) values
  ('Archer_Pull-Up', 'Archer Pull-Up', array['Archer Pullup']::text[], 'strength', 'vertical_pull', 'compound', 'pull', 'expert', array['Grip a pull-up bar wider than your shoulders.', 'Pull yourself up toward one hand while the other arm stays straight out to the side.', 'Lower with control and alternate sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band-Assisted_Chin-Up', 'Band-Assisted Chin-Up', array['Banded Chin-Up', 'Band Assisted Chin-Up']::text[], 'strength', 'vertical_pull', 'compound', 'pull', 'beginner', array['Loop a thick band over the bar and place a foot or knee in the bottom of the loop.', 'Pull up with an underhand grip until your chin clears the bar.', 'Lower slowly. Use a thinner band as you get stronger.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Helms_Row', 'Helms Row', array['Chest-Supported Dumbbell Row Incline', 'Incline Bench Row']::text[], 'strength', 'horizontal_pull', 'compound', 'pull', 'intermediate', array['Set a bench to a low incline and lie face down with a dumbbell in each hand.', 'Row both dumbbells toward your hips, keeping your chest on the pad.', 'Squeeze your shoulder blades, then lower slowly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Kroc_Row', 'Kroc Row', array['Kroc Rows', 'Heavy Dumbbell Row']::text[], 'strength', 'horizontal_pull', 'compound', 'pull', 'expert', array['Place one hand on a bench or rack, hinge forward, and hold a heavy dumbbell in the other hand.', 'Row it up for high reps with controlled body English, keeping your back flat.', 'Use straps if grip limits you. Switch arms after your reps.']::text[], '{}'::text[], true, true, 'catalog'),
  ('L-Sit_Pull-Up', 'L-Sit Pull-Up', array['L Sit Pull-Up', 'L-Sit Pullup']::text[], 'strength', 'vertical_pull', 'compound', 'pull', 'expert', array['Hang from a pull-up bar and raise your legs straight out in front of you.', 'Pull up until your chin clears the bar, holding your legs level.', 'Lower under control without dropping your legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Plate-Loaded_Lat_Pulldown', 'Plate-Loaded Lat Pulldown', array['Plate Loaded Pulldown', 'Hammer Strength Pulldown']::text[], 'strength', 'vertical_pull', 'compound', 'pull', 'beginner', array['Sit in the machine, adjust the thigh pad, and grip the handles.', 'Pull the handles down toward your shoulders by driving your elbows to your sides.', 'Return slowly until your lats are fully stretched.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Ring_Pull-Up', 'Ring Pull-Up', array['Gymnastic Ring Pull-Up', 'Rings Pull-Up']::text[], 'strength', 'vertical_pull', 'compound', 'pull', 'intermediate', array['Hang from gymnastic rings with straight arms.', 'Pull your chest toward the rings, turning your palms toward each other at the top.', 'Lower under control. The rings move, so your shoulders have to work to stay stable.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Wide-Grip_Seated_Cable_Row', 'Wide-Grip Seated Cable Row', array['Wide Grip Cable Row', 'Wide Seated Row']::text[], 'strength', 'horizontal_pull', 'compound', 'pull', 'beginner', array['Sit at a cable row with a wide bar, knees slightly bent, and grip it wide with straight arms.', 'Pull the bar to your upper abdomen, driving your elbows out and back.', 'Squeeze your shoulder blades, then return slowly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Hammer_Curl', 'Band Hammer Curl', array['Resistance Band Hammer Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Stand on a band and hold the ends with palms facing each other.', 'Curl your hands up toward your shoulders, keeping your thumbs up and your elbows at your sides.', 'Lower slowly under control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Cable_Concentration_Curl', 'Cable Concentration Curl', array['Kneeling Cable Curl', 'One-Arm Cable Concentration Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Set a cable low, kneel or sit beside it, and brace your upper arm against your thigh.', 'Curl the handle toward your shoulder without moving your upper arm.', 'Lower slowly. Complete all reps, then switch arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Chin-Up_Hold', 'Chin-Up Hold', array['Chinup Hold', 'Flexed Arm Hang']::text[], 'strength', 'vertical_pull', 'isolation', 'static', 'intermediate', array['Step up so your chin is above a pull-up bar with an underhand grip.', 'Hold the top position with your arms bent and your body still.', 'Hold as long as you can, then lower slowly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Plate_Curl', 'Plate Curl', array['Weight Plate Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Hold a weight plate at its sides with your arms straight in front of your thighs.', 'Curl the plate up toward your chest, keeping your elbows near your sides.', 'Lower slowly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Seated_Hammer_Curl', 'Seated Hammer Curl', array['Seated DB Hammer Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Sit on a bench with dumbbells at your sides and palms facing in.', 'Curl both dumbbells up, keeping your thumbs up and elbows still.', 'Lower slowly under control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Single-Arm_Machine_Curl', 'Single-Arm Machine Curl', array['One-Arm Machine Curl', 'Single Arm Preacher Machine Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Sit at the machine, adjust the seat so your upper arm rests on the pad, and grip one handle.', 'Curl the handle up toward your shoulder.', 'Lower slowly. Complete all reps, then switch arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Waiter_Curl', 'Waiter Curl', array['Dumbbell Waiter Curl', 'Cupped Dumbbell Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Hold one end of a dumbbell upright in both hands, cupped under the top plate.', 'Curl it up toward your chest, keeping your elbows at your sides.', 'Lower slowly under control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Hack_Squat_Calf_Raise', 'Hack Squat Calf Raise', array['Hack Squat Machine Calf Raise']::text[], 'strength', 'isolation', 'isolation', 'push', 'beginner', array['Set up in the hack squat machine with the balls of your feet at the bottom edge of the platform.', 'Rise up on your toes as high as you can.', 'Lower slowly until your heels drop below the platform.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Arc_Trainer', 'Arc Trainer', array['Arc Trainer Cardio', 'Cross Trainer']::text[], 'cardio', 'cardio', null, null, 'beginner', array['Step on the machine and hold the handles, setting a comfortable resistance.', 'Move in a smooth, low-impact stride at a steady pace or in intervals.', 'Log your time and effort.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Basketball', 'Basketball', array['Basketball Game', 'Pickup Basketball', 'Hoops']::text[], 'cardio', 'cardio', null, null, 'beginner', array['Warm up with light jogging and shooting.', 'Play pickup or a game, or do drills.', 'Log your time when you''re done.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Cross-Country_Skiing', 'Cross-Country Skiing', array['XC Skiing', 'Nordic Skiing']::text[], 'cardio', 'cardio', null, null, 'intermediate', array['Start with a steady pace on flat or rolling ground.', 'Glide, using your arms and legs together in a rhythmic stride.', 'Log your time and distance.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dance', 'Dance', array['Dancing', 'Dance Class', 'Zumba']::text[], 'cardio', 'cardio', null, null, 'beginner', array['Pick a dance class, video, or free-dance session.', 'Keep moving with the music and build up intensity as you warm up.', 'Log your time when you''re done.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Golf', 'Golf', array['Round of Golf', 'Walking Golf']::text[], 'cardio', 'cardio', null, null, 'beginner', array['Walk the course instead of using a cart if you can for more exercise.', 'Play your round or practice at the range.', 'Log your time when you''re done.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Kayaking', 'Kayaking', array['Kayak', 'Paddling', 'Canoeing']::text[], 'cardio', 'cardio', null, null, 'beginner', array['Set up on the water with a paddle and life jacket.', 'Paddle at a steady pace, rotating your torso with each stroke.', 'Log your time and distance.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Martial_Arts', 'Martial Arts', array['Martial Arts Class', 'Jiu-Jitsu', 'Karate', 'Muay Thai', 'MMA']::text[], 'cardio', 'cardio', null, null, 'beginner', array['Warm up with a few minutes of light movement.', 'Train through the class: drills, technique, and sparring as your coach directs.', 'Log your time when you''re done.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Pickleball', 'Pickleball', array['Pickleball Game']::text[], 'cardio', 'cardio', null, null, 'beginner', array['Warm up with light movement and a few easy rallies.', 'Play your games, moving quickly around the court.', 'Log your time when you''re done.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Rock_Climbing', 'Rock Climbing', array['Climbing', 'Bouldering', 'Indoor Climbing']::text[], 'cardio', 'cardio', null, null, 'intermediate', array['Warm up with easy routes and stretch your shoulders and fingers.', 'Climb routes or boulder problems, resting between attempts.', 'Log your time when you''re done.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Soccer', 'Soccer', array['Soccer Game', 'Football (Soccer)', 'Futsal']::text[], 'cardio', 'cardio', null, null, 'beginner', array['Warm up with jogging and a few passes.', 'Play a game or drills, moving in bursts with short recoveries.', 'Log your time when you''re done.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Tennis', 'Tennis', array['Tennis Match', 'Tennis Lesson']::text[], 'cardio', 'cardio', null, null, 'beginner', array['Warm up with easy rallies and a little jogging.', 'Play your match or drills, moving side to side.', 'Log your time when you''re done.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Alternating_Dumbbell_Bench_Press', 'Alternating Dumbbell Bench Press', array['Alternating DB Bench Press', 'Alternate Dumbbell Press']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'beginner', array['Lie on a bench with a dumbbell in each hand pressed above your chest.', 'Lower one dumbbell to chest level while the other stays locked out.', 'Press it back up, then repeat on the other side.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Push-Up', 'Band Push-Up', array['Banded Push-Up', 'Resistance Band Push-Up']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'intermediate', array['Loop a band across your upper back and hold the ends under your palms in a push-up position.', 'Lower your chest to just above the floor.', 'Press up against the band''s resistance until your arms are straight.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Deficit_Push-Up', 'Deficit Push-Up', array['Deficit Pushup', 'Elevated Hands Push-Up']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'intermediate', array['Place your hands on plates, books, or blocks so your chest can drop below hand level.', 'Lower your chest as deep as is comfortable.', 'Press back up to straight arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Incline_Close-Grip_Bench_Press', 'Incline Close-Grip Bench Press', array['Incline CGBP']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'intermediate', array['Set a bench to a low incline, lie back, and grip the bar about shoulder-width.', 'Lower the bar to your upper chest with your elbows tucked.', 'Press the bar back up to straight arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Landmine_Squeeze_Press', 'Landmine Squeeze Press', array['Landmine Svend Press', 'Landmine Chest Press']::text[], 'strength', 'other', 'compound', 'push', 'intermediate', array['Stand holding the end of a landmine bar with both hands against your chest, palms squeezing together.', 'Press the bar forward until your arms are straight, squeezing your hands together.', 'Return slowly to your chest.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Larsen_Press', 'Larsen Press', array['Feet-Up Bench Press']::text[], 'strength', 'other', 'compound', 'push', 'intermediate', array['Lie on a bench with your feet extended off the floor in front of you.', 'Lower the bar to your chest under control.', 'Press it back up. Without leg drive, your chest and arms do the work.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Machine_Pullover', 'Machine Pullover', array['Pullover Machine', 'Seated Pullover Machine']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Sit in the machine with your elbows on the pads.', 'Sweep the bar in an arc from overhead down toward your hips.', 'Return slowly until your lats are stretched.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Medicine_Ball_Push-Up', 'Medicine Ball Push-Up', array['Med Ball Push-Up', 'Medicine Ball Pushup']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'intermediate', array['Place one or both hands on a medicine ball in a push-up position.', 'Lower your chest toward the ball while keeping your body straight.', 'Press up and keep the ball steady.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Pseudo_Planche_Push-Up', 'Pseudo Planche Push-Up', array['Planche Lean Push-Up', 'Pseudo Planche Pushup']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'expert', array['Start in a push-up position with your hands by your hips, fingers pointing back or out.', 'Lean your shoulders forward past your hands and lower your chest.', 'Press back up keeping the lean.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Single-Arm_Incline_Dumbbell_Press', 'Single-Arm Incline Dumbbell Press', array['One-Arm Incline Dumbbell Press']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'intermediate', array['Lie on an incline bench holding one dumbbell at your shoulder.', 'Press it up to straight arms without letting your torso twist.', 'Lower slowly. Complete all reps, then switch arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Single-Arm_Machine_Chest_Press', 'Single-Arm Machine Chest Press', array['One-Arm Chest Press Machine']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'beginner', array['Sit in the machine with your back against the pad and grip one handle at chest height.', 'Press the handle forward until your arm is straight.', 'Return slowly. Complete all reps, then switch arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Spoto_Press', 'Spoto Press', array['Spoto Bench Press']::text[], 'strength', 'other', 'compound', 'push', 'intermediate', array['Set up as for a normal bench press.', 'Lower the bar until it is about an inch above your chest and pause there without touching.', 'Press back up to straight arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Straight_Bar_Dip', 'Straight Bar Dip', array['Bar Dip', 'Straight-Bar Dip']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'intermediate', array['Jump up and support yourself over a straight bar with straight arms.', 'Lower yourself until the bar is at your lower chest, leaning slightly forward.', 'Press back up to straight arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Agility_Ladder_Drills', 'Agility Ladder Drills', array['Ladder Drills', 'Speed Ladder']::text[], 'strength', 'other', null, null, 'beginner', array['Lay a ladder flat on the floor.', 'Step through the squares quickly with patterns like one-foot, two-feet, and lateral steps.', 'Stay light on the balls of your feet and keep your eyes up.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Battle_Rope_Slams', 'Battle Rope Slams', array['Rope Slams', 'Battle Rope Double Slam']::text[], 'strength', 'other', 'compound', 'push', 'beginner', array['Hold the ends of a battle rope with both hands and stand with feet shoulder-width apart.', 'Raise both arms overhead and slam the ropes down hard.', 'Let the ropes bounce back and repeat quickly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Crab_Walk', 'Crab Walk', array['Crab Walks']::text[], 'strength', 'other', 'compound', 'pull', 'beginner', array['Sit with your hands behind you and feet flat, then lift your hips off the floor.', 'Walk forward, backward, or sideways with your hips high.', 'Keep your hips up and move in a controlled way.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Heavy_Bag_Boxing', 'Heavy Bag Boxing', array['Heavy Bag Work', 'Boxing Bag', 'Punching Bag']::text[], 'strength', 'other', null, null, 'beginner', array['Wrap your hands or wear gloves and stand in a boxing stance in front of the bag.', 'Throw punches in combinations, turning your hips and moving around the bag.', 'Work in rounds of 2 to 3 minutes with short rests.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Man_Maker', 'Man Maker', array['Man Makers', 'Dumbbell Man Maker']::text[], 'strength', 'other', 'compound', 'push', 'expert', array['Hold dumbbells on the floor in a plank position and do a push-up.', 'Row each dumbbell to your ribs one at a time, then jump your feet in.', 'Clean the dumbbells to your shoulders, stand, and press overhead.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Pogo_Jumps', 'Pogo Jumps', array['Pogo Hops', 'Ankle Hops']::text[], 'strength', 'other', 'compound', 'push', 'beginner', array['Stand tall with your knees almost straight.', 'Hop up and down using only your ankles, landing on the balls of your feet.', 'Stay quick and light, as if the floor is hot.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Sandbag_Bear-Hug_Carry', 'Sandbag Bear-Hug Carry', array['Sandbag Carry', 'Bear Hug Carry']::text[], 'strength', 'carry', 'compound', 'pull', 'beginner', array['Lift a sandbag and hug it tightly against your chest.', 'Walk a set distance keeping your torso upright.', 'Set the bag down under control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Sandbag_Clean', 'Sandbag Clean', array['Sandbag Clean to Shoulder']::text[], 'strength', 'hinge', 'compound', 'pull', 'intermediate', array['Stand over a sandbag with your hips hinged and your back flat.', 'Pull the bag up explosively and drop under it, catching it at your shoulder or chest.', 'Stand tall, then lower it back to the floor.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Single-Leg_Box_Jump', 'Single-Leg Box Jump', array['Single Leg Box Jump']::text[], 'strength', 'other', 'compound', 'push', 'expert', array['Stand on one foot facing a low box.', 'Swing your arms and jump up, landing softly on the same foot on top.', 'Step down and reset. Start low.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Squat_Thrust', 'Squat Thrust', array['Squat Thrusts']::text[], 'strength', 'squat', 'compound', 'push', 'beginner', array['From standing, squat down and place your hands on the floor.', 'Kick your feet back into a plank, then jump them back in.', 'Stand up and repeat.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Dead_Bug', 'Band Dead Bug', array['Banded Dead Bug', 'Resistance Band Dead Bug']::text[], 'strength', 'core', 'isolation', 'pull', 'intermediate', array['Lie on your back holding a band anchored overhead, arms straight above your chest.', 'Lower the opposite arm and leg while pulling against the band, keeping your lower back flat.', 'Return and alternate sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Cross-Body_Mountain_Climber', 'Cross-Body Mountain Climber', array['Cross Body Mountain Climber', 'Oblique Mountain Climber']::text[], 'strength', 'core', 'compound', 'pull', 'beginner', array['Start in a high plank.', 'Drive one knee toward the opposite elbow, then switch legs.', 'Move at a steady pace, keeping your hips level.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Sandbag_Get-Up', 'Sandbag Get-Up', array['Sandbag Getup', 'Sandbag Turkish Get-Up']::text[], 'strength', 'core', 'compound', 'pull', 'expert', array['Lie on your back holding a sandbag on one shoulder.', 'Stand up from the floor in a controlled sequence while keeping the bag on your shoulder.', 'Reverse the steps to lie back down.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Slider_Pike', 'Slider Pike', array['Sliding Pike', 'Towel Pike']::text[], 'strength', 'core', 'compound', 'pull', 'intermediate', array['Start in a plank with your feet on sliders or towels on a smooth floor.', 'Slide your feet in toward your hands as you lift your hips high.', 'Slide back out to a plank slowly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Standing_Ab_Wheel_Rollout', 'Standing Ab Wheel Rollout', array['Standing Rollout', 'Standing Ab Roller']::text[], 'strength', 'core', 'compound', 'pull', 'expert', array['Stand holding an ab wheel on the floor in front of you.', 'Roll the wheel out as far as you can while keeping your body straight.', 'Pull it back in by squeezing your abs. Start with a short range.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Weighted_Decline_Sit-Up', 'Weighted Decline Sit-Up', array['Decline Sit-Up With Weight', 'Weighted Decline Situp']::text[], 'strength', 'core', 'compound', 'pull', 'intermediate', array['Lie on a decline bench with your feet secured, holding a plate or dumbbell at your chest.', 'Curl up until your torso is upright.', 'Lower slowly until your back is just above the bench.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Weighted_Plank', 'Weighted Plank', array['Plank With Weight', 'Loaded Plank']::text[], 'strength', 'core', 'compound', 'static', 'intermediate', array['Get in a forearm or high plank with a plate placed on your upper back, or wear a weight vest.', 'Keep your body in a straight line, squeezing your glutes and abs.', 'Hold as long as you can. Have a partner place the plate.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Wrist_Extension', 'Band Wrist Extension', array['Resistance Band Wrist Extension']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Sit with your forearm on your thigh, palm down, holding a band with the other end under your foot.', 'Extend your wrist up against the band.', 'Lower slowly. Complete all reps, then switch arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dumbbell_Wrist_Deviation', 'Dumbbell Wrist Deviation', array['Radial Deviation', 'Hammer Wrist Raise']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Sit with your forearm on your thigh and hold a dumbbell upright by one end, thumb on top.', 'Raise the weight by bending your wrist up toward your thumb side.', 'Lower slowly. Use a light weight and switch arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Reverse_Cable_Wrist_Curl', 'Reverse Cable Wrist Curl', array['Cable Wrist Extension']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Sit at a low cable with your forearm on your thigh and palm down holding a short bar.', 'Extend your wrist up, keeping your forearm still.', 'Lower slowly under control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Towel_Pull-Up', 'Towel Pull-Up', array['Towel Pullup', 'Towel Grip Pull-Up']::text[], 'strength', 'vertical_pull', 'compound', 'pull', 'expert', array['Drape two towels over a pull-up bar and grip them with both hands.', 'Pull up until your chin is near your hands.', 'Lower slowly. This builds grip strength alongside your back.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Adductor_Ball_Squeeze', 'Adductor Ball Squeeze', array['Ball Squeeze', 'Inner Thigh Ball Squeeze']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Lie on your back or sit with a ball between your knees.', 'Squeeze the ball hard with your inner thighs and hold for a few seconds.', 'Release and repeat.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Glute_Bridge_March', 'Glute Bridge March', array['Marching Glute Bridge', 'Bridge March']::text[], 'strength', 'hinge', 'compound', 'static', 'beginner', array['Lie on your back with knees bent and lift your hips into a bridge.', 'Lift one foot off the floor, then the other, without letting your hips drop.', 'Keep your hips level and your core braced.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Smith_Machine_Glute_Kickback', 'Smith Machine Glute Kickback', array['Smith Glute Kickback']::text[], 'strength', 'isolation', 'isolation', 'push', 'beginner', array['Set the Smith bar low and place the sole of one foot against it while on your hands and knees.', 'Press the bar up by driving your heel toward the ceiling.', 'Lower slowly. Complete all reps, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('American_Kettlebell_Swing', 'American Kettlebell Swing', array['American Swing', 'Overhead Kettlebell Swing']::text[], 'strength', 'hinge', 'compound', 'pull', 'intermediate', array['Swing the kettlebell between your legs, hinging at the hips.', 'Drive your hips forward and swing the bell all the way overhead.', 'Control it back down and into the next rep.']::text[], '{}'::text[], true, true, 'catalog'),
  ('B-Stance_RDL', 'B-Stance RDL', array['B Stance Romanian Deadlift', 'Kickstand RDL', 'Staggered Stance RDL']::text[], 'strength', 'hinge', 'compound', 'pull', 'beginner', array['Hold dumbbells and stand with one foot slightly behind the other, resting on its toes.', 'Hinge at the hips with a flat back, lowering the weights down your front leg.', 'Drive your hips forward to stand. Do all reps, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Leg_Press', 'Band Leg Press', array['Resistance Band Leg Press', 'Lying Band Leg Press']::text[], 'strength', 'squat', 'compound', 'push', 'beginner', array['Lie on your back with a band looped around your feet, holding the ends by your shoulders.', 'Press your feet away against the band until your legs are nearly straight.', 'Return slowly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Barbell_Single-Leg_RDL', 'Barbell Single-Leg RDL', array['Barbell One-Leg RDL']::text[], 'strength', 'hinge', 'compound', 'pull', 'intermediate', array['Hold a barbell in front of your thighs and balance on one leg.', 'Hinge at the hips, sending your free leg back as the bar lowers toward your shin.', 'Drive your hips forward to stand. Do all reps, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Cable_Squat', 'Cable Squat', array['Cable Goblet Squat', 'Standing Cable Squat']::text[], 'strength', 'squat', 'compound', 'push', 'beginner', array['Attach a rope or handle to a low cable and hold it at your chest.', 'Squat down between your knees with your chest tall.', 'Drive back up to standing.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Deficit_Reverse_Lunge', 'Deficit Reverse Lunge', array['Elevated Reverse Lunge', 'Reverse Lunge Deficit']::text[], 'strength', 'lunge', 'compound', 'push', 'intermediate', array['Stand on a low box or plate holding dumbbells at your sides.', 'Step back off the platform and lower your back knee toward the floor.', 'Drive through your front foot to return, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Goblet_Reverse_Lunge', 'Goblet Reverse Lunge', array['Goblet Rear Lunge']::text[], 'strength', 'lunge', 'compound', 'push', 'beginner', array['Hold a dumbbell or kettlebell at your chest and stand tall.', 'Step back and lower your back knee toward the floor.', 'Push through your front foot to return, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Landmine_Reverse_Lunge', 'Landmine Reverse Lunge', array['Landmine Rear Lunge']::text[], 'strength', 'lunge', 'compound', 'push', 'beginner', array['Hold the end of a landmine bar at your shoulder or chest and stand tall.', 'Step back and lower your back knee toward the floor.', 'Push through your front foot to return, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Landmine_Romanian_Deadlift', 'Landmine Romanian Deadlift', array['Landmine RDL']::text[], 'strength', 'hinge', 'compound', 'pull', 'beginner', array['Hold the end of a landmine bar in both hands in front of your thighs.', 'Hinge at the hips with a flat back and the bar sliding along your legs.', 'Drive your hips forward to stand tall.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Low-Bar_Squat', 'Low-Bar Squat', array['Low Bar Back Squat', 'Powerlifting Squat']::text[], 'strength', 'squat', 'compound', 'push', 'intermediate', array['Set the bar across your rear delts, lower on your back than for a high-bar squat, with your torso leaning forward.', 'Sit your hips back and down until your thighs are parallel to the floor or lower.', 'Drive up through your whole foot to stand.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Pause_Front_Squat', 'Pause Front Squat', array['Paused Front Squat']::text[], 'strength', 'squat', 'compound', 'push', 'intermediate', array['Rest the bar on the front of your shoulders and unrack it.', 'Squat to full depth and hold the bottom for 2 to 3 seconds, keeping your chest tall.', 'Drive up out of the hole.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Paused_Deadlift', 'Paused Deadlift', array['Pause Deadlift']::text[], 'strength', 'hinge', 'compound', 'pull', 'intermediate', array['Set up over the bar as for a normal deadlift.', 'Lift the bar to just below your knees and hold for 2 seconds.', 'Finish the lift to standing and lower under control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Reverse_Hack_Squat', 'Reverse Hack Squat', array['Reverse Hack Squat Machine', 'Reverse-Grip Hack Squat']::text[], 'strength', 'squat', 'compound', 'push', 'intermediate', array['Face the pad in a hack squat machine with your chest on it and feet on the platform.', 'Lower your body down by bending your knees and hips.', 'Drive back up, squeezing your glutes.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Safety_Squat_Bar_Split_Squat', 'Safety Squat Bar Split Squat', array['SSB Split Squat']::text[], 'strength', 'lunge', 'compound', 'push', 'intermediate', array['Set the safety squat bar on your upper back and unrack it.', 'Step into a split stance and lower your back knee toward the floor.', 'Push through your front foot to rise, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Sandbag_Squat', 'Sandbag Squat', array['Sandbag Front Squat', 'Sandbag Bear Hug Squat']::text[], 'strength', 'squat', 'compound', 'push', 'beginner', array['Hug a sandbag against your chest.', 'Squat down until your thighs are parallel to the floor.', 'Drive back up to standing.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Single-Leg_Seated_Leg_Curl', 'Single-Leg Seated Leg Curl', array['One-Leg Seated Leg Curl']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Sit in the seated leg curl machine and place one ankle under the pad, with the other leg off the pad.', 'Curl your heel back and down as far as you can.', 'Return slowly. Complete all reps, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Slider_Reverse_Lunge', 'Slider Reverse Lunge', array['Sliding Reverse Lunge', 'Gliding Lunge']::text[], 'strength', 'lunge', 'compound', 'push', 'intermediate', array['Stand with one foot on a slider or towel on a smooth floor.', 'Slide that foot straight back and lower your back knee toward the floor.', 'Pull yourself back to standing with your front leg.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Smith_Machine_Box_Squat', 'Smith Machine Box Squat', array['Smith Box Squat']::text[], 'strength', 'squat', 'compound', 'push', 'beginner', array['Place a box or bench behind you under the Smith bar and rest the bar on your upper back.', 'Sit back and down until you lightly touch the box, then drive up.', 'Keep your torso tight and avoid bouncing off the box.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Smith_Machine_Deadlift', 'Smith Machine Deadlift', array['Smith Deadlift']::text[], 'strength', 'hinge', 'compound', 'pull', 'beginner', array['Set the Smith bar low and stand with it over your midfoot.', 'Hinge with a flat back, grip the bar, and stand tall driving your hips forward.', 'Lower it under control by hinging back.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Smith_Machine_Hack_Squat', 'Smith Machine Hack Squat', array['Smith Hack Squat']::text[], 'strength', 'squat', 'compound', 'push', 'beginner', array['Hold the Smith bar behind your legs with straight arms and your feet slightly in front.', 'Squat down with your chest up and the bar sliding down your legs.', 'Drive back up to standing.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Spanish_Squat', 'Spanish Squat', array['Spanish Squat Hold', 'Band Squat Hold']::text[], 'strength', 'squat', 'isolation', 'static', 'beginner', array['Anchor a heavy band at knee height and loop it behind your knees, then lean back against it.', 'Sit back into a squat with your shins vertical and your weight on your heels.', 'Hold the position. It is easy on the knees and builds your quads.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Trap_Bar_Jump', 'Trap Bar Jump', array['Hex Bar Jump', 'Trap Bar Jump Squat']::text[], 'strength', 'other', 'compound', 'push', 'intermediate', array['Stand inside a light trap bar and hold the handles.', 'Dip slightly, then jump as high as you can.', 'Land softly and reset before the next jump.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Wide-Stance_Leg_Press', 'Wide-Stance Leg Press', array['Wide Stance Leg Press', 'Sumo Leg Press']::text[], 'strength', 'squat', 'compound', 'push', 'beginner', array['Place your feet wide and slightly turned out on the leg press platform.', 'Lower the platform until your knees are bent about 90 degrees.', 'Press back up without locking your knees.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Dumbbell_Good_Morning', 'Dumbbell Good Morning', array['DB Good Morning', 'Goblet Good Morning']::text[], 'strength', 'hinge', 'compound', 'pull', 'beginner', array['Hold a dumbbell at your chest with your feet hip-width apart.', 'Hinge at the hips with a flat back until your torso is nearly parallel to the floor.', 'Drive your hips forward to stand tall.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Jefferson_Curl', 'Jefferson Curl', array['Jefferson Curls']::text[], 'strength', 'isolation', 'isolation', 'pull', 'expert', array['Stand on a bench or plate holding a very light weight.', 'Slowly curl forward one vertebra at a time until the weight hangs below your feet.', 'Reverse the curl slowly to stand. Always use a very light weight.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Safety_Squat_Bar_Good_Morning', 'Safety Squat Bar Good Morning', array['SSB Good Morning']::text[], 'strength', 'squat', 'compound', 'pull', 'intermediate', array['Set the safety squat bar on your upper back and unrack it.', 'Hinge at the hips with soft knees until your torso is nearly parallel to the floor.', 'Drive your hips forward to stand tall.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Hip_CARs', 'Hip CARs', array['Hip Controlled Articular Rotations', 'Hip Circles']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['Stand or kneel on all fours and brace your core.', 'Draw the largest slow circle you can with your knee, keeping your torso still.', 'Do the same number of circles in each direction, then switch legs.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Scorpion_Stretch', 'Scorpion Stretch', array['Scorpion Pose', 'Scorpion Kick']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['Lie face down with your arms out to the sides.', 'Bring one heel up and across your body toward the opposite hand, rotating your hips.', 'Hold briefly, then switch sides.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Shoulder_CARs', 'Shoulder CARs', array['Shoulder Controlled Articular Rotations', 'Arm Circles Slow']::text[], 'stretching', 'mobility', null, 'static', 'beginner', array['Stand tall with your arm at your side and your core braced.', 'Make the largest slow circle you can with your arm, keeping your ribs still.', 'Do the same number in each direction, then switch arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Behind-the-Neck_Jerk', 'Behind-the-Neck Jerk', array['Behind the Neck Jerk']::text[], 'strength', 'vertical_push', 'compound', 'push', 'expert', array['Rest the bar behind your neck and unrack it.', 'Dip and drive with your legs, punching the bar overhead and splitting or dipping under it.', 'Recover to standing and lower the bar to your shoulders.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Hang_Power_Snatch', 'Hang Power Snatch', array['Power Snatch From Hang']::text[], 'strength', 'hinge', 'compound', 'pull', 'expert', array['Hold the bar with a wide grip at your thighs, hips hinged.', 'Explosively extend and pull the bar overhead, catching it in a quarter squat.', 'Stand tall and lower the bar under control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Muscle_Clean', 'Muscle Clean', array['Muscle Cleans']::text[], 'strength', 'hinge', 'compound', 'pull', 'intermediate', array['Hold the bar at your thighs with a clean grip.', 'Extend your hips and shrug, pulling the bar up your body with high elbows, without dipping under it.', 'Finish with the bar on your shoulders and lower under control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Sots_Press', 'Sots Press', array['Sots Press Squat']::text[], 'strength', 'other', 'compound', 'push', 'expert', array['Sit in the bottom of a squat with the bar racked at your shoulders.', 'Press the bar overhead from the deep squat.', 'Lower the bar under control and stand up only when done.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Tall_Clean', 'Tall Clean', array['Tall Cleans']::text[], 'strength', 'hinge', 'compound', 'pull', 'intermediate', array['Stand tall holding the bar at your thighs.', 'Shrug and pull the bar up, dropping under it into a quick catch on your shoulders.', 'Stand tall and lower under control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Axle_Press', 'Axle Press', array['Axle Bar Overhead Press', 'Fat Bar Press']::text[], 'strength', 'other', 'compound', 'push', 'intermediate', array['Unrack the axle bar to your shoulders.', 'Press it overhead to lock out, keeping your core braced.', 'Lower under control to your shoulders.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Behind-the-Back_Cable_Lateral_Raise', 'Behind-the-Back Cable Lateral Raise', array['Behind the Back Cable Lateral Raise']::text[], 'strength', 'isolation', 'isolation', 'pull', 'intermediate', array['Stand with a low cable behind your body and the handle in your far hand.', 'Raise your arm out to the side to shoulder height.', 'Lower slowly. Complete all reps, then switch arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Kettlebell_Bottoms-Up_Press', 'Kettlebell Bottoms-Up Press', array['Bottoms Up Kettlebell Press']::text[], 'strength', 'other', 'compound', 'push', 'intermediate', array['Hold a kettlebell upside down by the handle at shoulder height.', 'Press it overhead, keeping the bell balanced.', 'Lower under control. Go light, as balancing the bell is hard.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Lu_Raise', 'Lu Raise', array['Lu Xiaojun Raise', 'Lu Lateral Raise']::text[], 'strength', 'isolation', 'isolation', 'pull', 'intermediate', array['Hold light dumbbells or plates in front of your thighs.', 'Raise your arms out and up in a wide arc until they are overhead, with thumbs up.', 'Lower slowly the same way.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Viking_Press', 'Viking Press', array['Viking Press Machine', 'Landmine Viking Press']::text[], 'strength', 'other', 'compound', 'push', 'intermediate', array['Stand holding the Viking press handles at shoulder height.', 'Press the weights up until your arms are straight.', 'Lower slowly to your shoulders.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Axle_Clean_and_Press', 'Axle Clean and Press', array['Axle Bar Clean and Press']::text[], 'strength', 'hinge', 'compound', 'push', 'expert', array['Pull the axle bar from the floor to your shoulders in one clean motion.', 'Press it overhead to lock out.', 'Lower to your shoulders and then to the floor.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Circus_Dumbbell_Press', 'Circus Dumbbell Press', array['Circus DB Press', 'Circus Dumbbell']::text[], 'strength', 'vertical_push', 'compound', 'push', 'expert', array['Lift a heavy circus dumbbell to your shoulder.', 'Press it overhead with a clean lockout.', 'Lower it back under control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Frame_Carry', 'Frame Carry', array['Carry Frame', 'Frame Walk']::text[], 'strength', 'carry', 'compound', 'pull', 'intermediate', array['Step inside the carry frame and grip the handles.', 'Lift it and walk a set distance, staying tall.', 'Set it down with control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Husafell_Stone_Carry', 'Husafell Stone Carry', array['Husafell Carry']::text[], 'strength', 'carry', 'compound', 'pull', 'expert', array['Hug the stone to your chest.', 'Walk a set distance with your torso upright.', 'Set it down with control.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Keg_Carry', 'Keg Carry', array['Keg Carry Walk', 'Keg Walk']::text[], 'strength', 'carry', 'compound', 'pull', 'intermediate', array['Lift the keg and hug it against your chest.', 'Walk a set distance with your torso upright.', 'Set it down carefully.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Shrug', 'Band Shrug', array['Resistance Band Shrug']::text[], 'strength', 'isolation', 'isolation', 'pull', 'beginner', array['Stand on a band and hold the ends with straight arms.', 'Shrug your shoulders straight up toward your ears.', 'Hold briefly, then lower slowly.']::text[], '{}'::text[], true, true, 'catalog'),
  ('EZ-Bar_Upright_Row', 'EZ-Bar Upright Row', array['EZ Bar Upright Row', 'Curl Bar Upright Row']::text[], 'strength', 'other', 'compound', 'pull', 'intermediate', array['Hold an EZ bar with a narrow grip in front of your thighs.', 'Pull it up toward your chest, leading with your elbows.', 'Lower slowly. Stop at chest height.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Band_Tricep_Kickback', 'Band Tricep Kickback', array['Resistance Band Kickback']::text[], 'strength', 'isolation', 'isolation', 'push', 'beginner', array['Stand on a band, hinge forward, and hold the other end with your upper arm tucked against your side.', 'Extend your elbow until your arm is straight behind you.', 'Return slowly. Complete all reps, then switch arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('California_Press', 'California Press', array['California Skull Crusher']::text[], 'strength', 'isolation', 'isolation', 'push', 'intermediate', array['Lie on a bench holding a barbell above your chest with a narrow grip.', 'Lower the bar toward your head by bending your elbows, then let it drift toward your chest as you press up.', 'Press up to straight arms, keeping your elbows pointing forward.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Close-Grip_Floor_Press', 'Close-Grip Floor Press', array['Close Grip Floor Press']::text[], 'strength', 'horizontal_push', 'compound', 'push', 'beginner', array['Lie on the floor with a barbell above your chest and your hands about shoulder-width apart.', 'Lower the bar until your upper arms touch the floor.', 'Press it back up to straight arms.']::text[], '{}'::text[], true, true, 'catalog'),
  ('Incline_Dumbbell_Skull_Crusher', 'Incline Dumbbell Skull Crusher', array['Incline DB Skull Crusher']::text[], 'strength', 'isolation', 'isolation', 'push', 'intermediate', array['Lie on a low incline bench holding dumbbells above your chest.', 'Bend your elbows to lower the weights toward your head, keeping your upper arms still.', 'Extend back up to straight arms.']::text[], '{}'::text[], true, true, 'catalog')
